import{_ as a,o as r,c as l,a2 as e}from"./chunks/framework.wVcpyw2-.js";const S=JSON.parse('{"title":"邮箱配置","description":"灵萌 SMTP 邮箱发信配置：主机端口、加密方式、测试邮件与常见问题。","frontmatter":{"title":"邮箱配置","description":"灵萌 SMTP 邮箱发信配置：主机端口、加密方式、测试邮件与常见问题。"},"headers":[],"relativePath":"config/email.md","filePath":"config/email.md","lastUpdated":1785051348000}'),i={name:"config/email.md"};function o(d,t,n,s,h,c){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="邮箱配置" tabindex="-1">邮箱配置 <a class="header-anchor" href="#邮箱配置" aria-label="Permalink to &quot;邮箱配置&quot;">​</a></h1><p>路径：<strong>系统设置 → 邮箱配置</strong></p><p>配置全站 SMTP，用于系统发信（如找回密码、部分告警或运营邮件，以实际业务接入为准）。密码仅安全存储，界面不显示明文。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已有可用的邮箱 SMTP（企业邮箱、云厂商 SMTP 等）</li><li>知道主机、端口、加密方式（无 / SSL / STARTTLS）、账号密码</li><li>具备系统设置相关权限</li></ul><hr><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><ol><li>打开 <strong>系统设置 → 邮箱配置</strong></li><li><strong>启用 SMTP</strong> 选「启用」</li><li>填写 SMTP： <ul><li><strong>主机</strong></li><li><strong>端口</strong>（如 465、587）</li><li><strong>加密方式</strong>：无 / SSL / STARTTLS（须与端口匹配，465 常用 SSL）</li><li><strong>用户名</strong>、<strong>密码</strong>（留空密码表示不修改已保存的密码）</li></ul></li><li>填写 <strong>发件人名称</strong>、<strong>发件邮箱</strong></li><li>点 <strong>保存配置</strong></li><li>填写测试收件人 → <strong>发送测试邮件</strong>，确认能收到</li></ol><hr><h2 id="字段速查" tabindex="-1">字段速查 <a class="header-anchor" href="#字段速查" aria-label="Permalink to &quot;字段速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>启用 SMTP</td><td>关闭后系统不会尝试通过 SMTP 发信</td></tr><tr><td>主机 / 端口 / 加密</td><td>与邮箱服务商文档一致</td></tr><tr><td>发件人名称 / 发件邮箱</td><td>收件人看到的发件显示</td></tr><tr><td>配置 ID、创建/更新时间</td><td>只读系统信息</td></tr></tbody></table><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>保存后发送测试邮件成功</li><li>触发一条会发邮件的业务（如找回密码，若已接入），收件箱可见</li><li>失败时检查垃圾箱、服务商是否拦截、端口是否被服务器防火墙挡住</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>测试失败、连接超时</td><td>服务器出网；安全组放行 SMTP 端口；主机地址是否写错</td></tr><tr><td>认证失败</td><td>用户名/密码错误；部分厂商需「授权码」而非登录密码</td></tr><tr><td>SSL 报错</td><td>加密方式与端口不匹配（465↔SSL，587↔STARTTLS）</td></tr><tr><td>保存后密码好像丢了</td><td>编辑时密码留空表示不改；若要改必须重新填写新密码再保存</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/config/system-settings">系统配置总览</a></li><li><a href="/config/user-rules">用户规则</a></li></ul>',21)])])}const u=a(i,[["render",o]]);export{S as __pageData,u as default};
